class Cache:
    def __init__(self):
        self.store = {}
        self.cached = {}

    def put(self, key, value):
        self.store[key] = value
        self.cached.pop(key, None)

    def get(self, key):
        if key not in self.cached:
            self.cached[key] = self.store.get(key)
        return self.cached[key]

    def delete(self, key):
        self.store.pop(key, None)

